arguments.argument:
xoffset = view_xview[0];
yoffset = view_yview[0];
xsize = view_wview[0];
ysize = view_hview[0];

classSelectOffset = xsize/2-sprite_get_width(LoadoutSelectS)/2+xoffset

if !instance_exists(Back) instance_create(32+view_xview[0],544+yoffset,Back);

if mouse_x>classSelectOffset+0 && mouse_x <classSelectOffset+36 && mouse_y<yoffset+60{
    newclass=0;
    drawx=0;
}

else if mouse_x>classSelectOffset+40 && mouse_x <classSelectOffset+76 && mouse_y<yoffset+60{
    newclass=1;
    drawx=40;
}

else if mouse_x>classSelectOffset+80 && mouse_x <classSelectOffset+116 && mouse_y<yoffset+60{
    newclass=2;
    drawx=80;
}

else if mouse_x>classSelectOffset+132 && mouse_x <classSelectOffset+168 && mouse_y<yoffset+60{
    newclass=3;
    drawx=132;
}

else if mouse_x>classSelectOffset+172 && mouse_x <classSelectOffset+208 && mouse_y<yoffset+60{
    newclass=4;
    drawx=172;
}

else if mouse_x>classSelectOffset+212 && mouse_x <classSelectOffset+248 && mouse_y<yoffset+60{
    newclass=5;
    drawx=212;
}

else if mouse_x>classSelectOffset+264 && mouse_x <classSelectOffset+300 && mouse_y<yoffset+60{
    newclass=6;
    drawx=264;
}

else if mouse_x>classSelectOffset+304 && mouse_x <classSelectOffset+340 && mouse_y<yoffset+60{
    newclass=7;
    drawx=304;
}

else if mouse_x>classSelectOffset+344 && mouse_x <classSelectOffset+380 && mouse_y<yoffset+60{
    newclass=8;
    drawx=344;
}

else newclass=-1;  

if mouse_check_button(mb_left){ 
    if newclass !=-1{
        mousedclass = newclass;
        if(newclass>=0 and newclass<=9) {
            if instance_exists(LoadoutSwitcher) event_user(1); //get rid of the loadout for the old class and write their loadout to the file
            event_user(2); //create the loadout for the new class
        }
    }else if mouse_y > (250-104)+yoffset && mouse_y < (250+104)+yoffset{
        if mouse_x > (300-100)+xoffset && mouse_x < (300+100)+xoffset {
            if firstX == -1 firstX=mouse_x;
            else if firstX > mouse_x + 10{
                rotation= -1;
                firstX=-1;
            }
            else if firstX < mouse_x - 10{
                rotation= 1;
                firstX=-1;
            }
        }
    }
} else if firstX != -1 firstX = -1;
stepHasRun = true;
